TEMPLATE = '<!DOCTYPE html>\n<html lang="en">\n<head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1">\n<title>AI Job Tracker</title>\n<style>\n  *{box-sizing:border-box}\n  body{margin:0;font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,sans-serif;background:#f0f2f5;color:#1a1a2e}\n  .hdr{background:linear-gradient(135deg,#0f0c29,#302b63,#24243e);color:#fff;padding:32px 48px 28px;display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:16px}\n  .hdr-left h1{margin:0 0 4px;font-size:1.6rem;font-weight:700;letter-spacing:-.5px}\n  .hdr-left .sub{font-size:.85rem;opacity:.6}\n  .hdr-badges{display:flex;gap:10px;flex-wrap:wrap}\n  .hdr-badge{background:rgba(255,255,255,.12);border:1px solid rgba(255,255,255,.2);border-radius:20px;padding:5px 14px;font-size:.82rem;font-weight:600}\n  .hdr-badge.new{background:rgba(30,136,229,.35);border-color:rgba(30,136,229,.6)}\n  .page{max-width:1280px;margin:0 auto;padding:28px 40px}\n  .cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(170px,1fr));gap:14px;margin-bottom:28px}\n  .card{background:#fff;border-radius:12px;padding:20px 22px;box-shadow:0 1px 4px rgba(0,0,0,.07);border-top:3px solid transparent}\n  .card .num{font-size:2.2rem;font-weight:800;line-height:1;margin-bottom:4px}\n  .card .lbl{font-size:.8rem;color:#888;font-weight:500;text-transform:uppercase;letter-spacing:.5px}\n  .sec{background:#fff;border-radius:12px;box-shadow:0 1px 4px rgba(0,0,0,.07);margin-bottom:22px;overflow:hidden}\n  .sec-hdr{padding:16px 24px 0;display:flex;align-items:center;gap:10px}\n  .sec-hdr .icon{width:28px;height:28px;border-radius:8px;display:flex;align-items:center;justify-content:center;font-size:14px;flex-shrink:0}\n  .sec-hdr h2{margin:0;font-size:1rem;font-weight:700;color:#222}\n  .sec-hdr .cnt{background:#f0f2f5;color:#555;border-radius:10px;padding:2px 9px;font-size:.78rem;font-weight:600;margin-left:auto}\n  .sec-body{padding:4px 24px 20px}\n  .overview-grid{display:grid;grid-template-columns:300px 1fr;gap:0;align-items:start}\n  .overview-pie{padding:16px 0 16px 16px}\n  .overview-bar{padding:16px 16px 0 0}\n  .highlight{background:linear-gradient(135deg,#fff8f0,#fff3e0);border-left:4px solid #f57c00;border-radius:12px;padding:18px 22px;margin-bottom:22px}\n  .highlight h3{margin:0 0 14px;color:#e65100;font-size:.95rem;font-weight:700}\n  .jcard{background:#fff;border:1px solid #ffe0b2;border-radius:8px;padding:12px 16px;margin-bottom:10px}\n  .jcard:last-child{margin-bottom:0}\n  .jcard-title{font-size:.9rem;font-weight:600;color:#1a1a2e}\n  .jcard-title a{color:#1a1a2e;text-decoration:none}\n  .jcard-title a:hover{color:#302b63;text-decoration:underline}\n  .jcard-meta{font-size:.78rem;color:#888;margin-top:3px}\n  .jcard-tags{display:flex;flex-wrap:wrap;gap:4px;margin-top:6px}\n  .trend-note{font-size:.8rem;color:#aaa;margin-left:8px;font-weight:400}\n  .tbl-wrap{overflow-x:auto}\n  table{width:100%;border-collapse:collapse;font-size:.84rem}\n  th{background:#f7f8fa;padding:9px 12px;text-align:left;font-size:.75rem;font-weight:700;color:#888;text-transform:uppercase;letter-spacing:.5px;white-space:nowrap;border-bottom:2px solid #eee}\n  td{padding:9px 12px;border-bottom:1px solid #f0f0f0;vertical-align:middle}\n  tr:last-child td{border-bottom:none}\n  tr:hover td{background:#fafafa}\n  .badge{display:inline-flex;align-items:center;padding:2px 9px;border-radius:20px;font-size:.72rem;font-weight:700;letter-spacing:.2px}\n  .badge-co{color:#fff}\n  .badge-v{background:#fff3e0;color:#e65100;border:1px solid #ffcc80}\n  .badge-cat{background:#f3f4f6;color:#555;border:1px solid #e0e0e0}\n  .tabs{display:flex;gap:0;border-bottom:2px solid #f0f0f0;padding:0 24px}\n  .tab{padding:10px 18px;font-size:.85rem;font-weight:600;color:#aaa;cursor:pointer;border-bottom:2px solid transparent;margin-bottom:-2px;transition:color .15s}\n  .tab.active{color:#302b63;border-bottom-color:#302b63}\n  .tab:hover:not(.active){color:#555}\n  @media(max-width:800px){.overview-grid{grid-template-columns:1fr}.page{padding:16px 18px}.hdr{padding:20px 24px}}\n</style>\n</head><body>\n\n<div class="hdr">\n  <div class="hdr-left">\n    <h1>AI Company Job Tracker</h1>\n    <div class="sub">{{ generated_at }}{% if run_type == \'weekly\' %} &nbsp;.&nbsp; Weekly Update since {{ since }}{% else %} &nbsp;.&nbsp; Initial Snapshot{% endif %}</div>\n  </div>\n  <div class="hdr-badges">\n    <div class="hdr-badge" style="border-color:#10a37f88;background:rgba(16,163,127,.2)">OpenAI &nbsp;<strong>{{ stats.by_company.get("openai",0) }}</strong></div>\n    <div class="hdr-badge" style="border-color:#d9775788;background:rgba(217,119,87,.2)">Anthropic &nbsp;<strong>{{ stats.by_company.get("anthropic",0) }}</strong></div>\n    <div class="hdr-badge">Total &nbsp;<strong>{{ stats.total }}</strong></div>\n    {% if run_type == "weekly" %}<div class="hdr-badge new">+{{ new_total }} new &nbsp;&middot;&nbsp; {{ new_vertical }} vertical</div>{% if removed_total > 0 %}<div class="hdr-badge" style="background:rgba(239,83,80,.25);border-color:rgba(239,83,80,.5)">&minus;{{ removed_total }} closed &nbsp;&middot;&nbsp; {{ removed_vertical }} vertical</div>{% endif %}{% endif %}\n  </div>\n</div>\n<div class="page">\n<div class="cards">\n  <div class="card" style="border-top-color:#10a37f">\n    <div class="num" style="color:#10a37f">{{ stats.by_company.get("openai",0) }}</div>\n    <div class="lbl">OpenAI Listings</div>\n  </div>\n  <div class="card" style="border-top-color:#d97757">\n    <div class="num" style="color:#d97757">{{ stats.by_company.get("anthropic",0) }}</div>\n    <div class="lbl">Anthropic Listings</div>\n  </div>\n  <div class="card" style="border-top-color:#302b63">\n    <div class="num" style="color:#302b63">{{ stats.total }}</div>\n    <div class="lbl">Total Active</div>\n  </div>\n  <div class="card" style="border-top-color:#e65100">\n    <div class="num" style="color:#e65100">{{ stats.vertical_domain_jobs }}</div>\n    <div class="lbl">Vertical-Domain</div>\n  </div>\n  {% if run_type == "weekly" %}\n  <div class="card" style="border-top-color:#1e88e5">\n    <div class="num" style="color:#1e88e5">+{{ new_total }}</div>\n    <div class="lbl">New This Week</div>\n  </div>\n  {% if removed_total > 0 %}\n  <div class="card" style="border-top-color:#ef5350">\n    <div class="num" style="color:#ef5350">&minus;{{ removed_total }}</div>\n    <div class="lbl">Closed This Week</div>\n  </div>\n  {% endif %}\n  {% endif %}\n</div>\n{% if run_type == "weekly" and new_vertical_jobs %}\n<div class="highlight">\n  <h3>New Vertical-Domain Listings This Week ({{ new_vertical_jobs|length }})</h3>\n  {% for j in new_vertical_jobs %}\n  <div class="jcard">\n    <div class="jcard-title"><a href="{{ j.url }}" target="_blank">{{ j.title }}</a>\n      &nbsp;<span class="badge badge-co" style="background:{{ company_color(j.company) }}">{{ company_label(j.company) }}</span></div>\n    <div class="jcard-meta">{{ company_label(j.company) }} &nbsp;&middot;&nbsp; {{ j.department }}{% if j.location %} &nbsp;&middot;&nbsp; {{ j.location }}{% endif %}</div>\n    <div class="jcard-tags">{% for dk in j.vertical_domains_list %}<span class="badge badge-v">{{ dom_label(dk) }}</span>{% endfor %}</div>\n  </div>\n  {% endfor %}\n</div>\n{% endif %}\n\n\n{% if run_type == "weekly" and removed_jobs %}\n<div class="sec">\n  <div class="sec-hdr">\n    <div class="icon" style="background:#ffebee">&#128683;</div>\n    <h2>Positions Closed This Week</h2>\n    <span class="cnt" style="background:#ffebee;color:#c62828">{{ removed_total }} closed &nbsp;&middot;&nbsp; {{ removed_vertical }} vertical</span>\n  </div>\n  <div class="sec-body">\n    {% if removed_vertical_jobs %}\n    <div style="background:#fff5f5;border-left:3px solid #ef5350;border-radius:6px;padding:10px 14px;margin-bottom:14px;font-size:.82rem;color:#c62828;font-weight:600">\n      Vertical-domain closures: {% for j in removed_vertical_jobs %}<span style="margin-right:10px">{{ company_label(j.company) }} &mdash; {{ j.title }}</span>{% endfor %}\n    </div>\n    {% endif %}\n    <div class="tbl-wrap">\n    <table>\n      <thead><tr>\n        <th>Company</th><th>Title</th><th>Dept / Team</th><th>Domain(s)</th><th>Open Since</th>\n      </tr></thead>\n      <tbody>\n      {% for j in removed_jobs %}\n      <tr>\n        <td><span class="badge badge-co" style="background:{{ company_color(j.company) }}">{{ company_label(j.company) }}</span></td>\n        <td style="color:#666;text-decoration:line-through">{{ j.title }}</td>\n        <td style="color:#999">{{ j.department }}</td>\n        <td>{% for dk in j.vertical_domains_list %}<span class="badge badge-v" style="margin:1px">{{ dom_label(dk) }}</span>{% endfor %}</td>\n        <td style="color:#999;white-space:nowrap;font-size:.78rem">{{ j.first_seen[:10] if j.first_seen else "" }}</td>\n      </tr>\n      {% endfor %}\n      </tbody>\n    </table>\n    </div>\n  </div>\n</div>\n{% endif %}\n\n<div class="sec">\n  <div class="sec-hdr"><div class="icon" style="background:#f0eeff">&#128202;</div>\n    <h2>Current Snapshot Overview</h2></div>\n  <div style="display:grid;grid-template-columns:260px 1fr;align-items:start;padding:8px 24px 4px">\n    <div style="padding:8px 0">{{ pie_html }}</div>\n    <div style="padding:8px 0 0 8px">\n      <div style="font-size:.78rem;font-weight:700;color:#aaa;text-transform:uppercase;letter-spacing:.5px;margin-bottom:6px;padding-left:4px">Headcount by Department / Team</div>\n      <div style="display:grid;grid-template-columns:1fr 1fr;gap:12px">\n        <div>{{ anthropic_dept_html }}</div>\n        <div>{{ openai_dept_html }}</div>\n      </div>\n    </div>\n  </div>\n</div>\n<div class="sec">\n  <div class="sec-hdr"><div class="icon" style="background:#fff3e0">&#127759;</div>\n    <h2>Vertical Industry Distribution</h2>\n    <span class="cnt">{{ stats.vertical_domain_jobs }} jobs</span></div>\n  <div class="sec-body">{% if stats.vertical_domain_jobs > 0 %}{{ domain_bar_html }}{% else %}<p style="color:#aaa;padding:16px 0">No vertical-domain jobs detected.</p>{% endif %}</div>\n</div>\n{% if run_type == "weekly" and new_cat_html %}\n<div class="sec">\n  <div class="sec-hdr"><div class="icon" style="background:#e8f5e9">+</div>\n    <h2>New Listings This Week by Category</h2>\n    <span class="cnt">{{ new_total }} new</span></div>\n  <div class="sec-body">{{ new_cat_html }}</div>\n</div>\n{% endif %}\n<div class="sec">\n  <div class="sec-hdr"><div class="icon" style="background:#e3f2fd">&#128200;</div>\n    <h2>Historical Trends</h2>\n    <span class="trend-note">{{ n_snapshots }} snapshot{{ "s" if n_snapshots != 1 else "" }} across {{ unique_dates }} week{{ "s" if unique_dates != 1 else "" }}</span></div>\n  {% if has_trends %}\n  <div class="tabs">\n    <div class="tab active">Total Listings</div>\n    <div class="tab">By Category</div>\n    <div class="tab">By Vertical Domain</div>\n  </div>\n  <div class="sec-body">\n    <div id="t0">{{ trend_total_html }}</div>\n    <div id="t1">{{ trend_cat_html }}</div>\n    <div id="t2">{{ trend_dom_html }}</div>\n  </div>\n  {% else %}\n  <div class="sec-body">\n    <div style="padding:32px 0;text-align:center;color:#bbb">\n      <div style="font-size:2rem;margin-bottom:10px">&#128337;</div>\n      <div style="font-size:.95rem;font-weight:500">Trends will appear after the next weekly run</div>\n      <div style="font-size:.82rem;margin-top:6px">Need data from at least 2 different weeks</div>\n    </div>\n  </div>\n  {% endif %}\n</div>\n{% if stats.domain_jobs_list %}\n<div class="sec">\n  <div class="sec-hdr"><div class="icon" style="background:#fce4ec">&#127991;</div>\n    <h2>All Vertical-Domain Listings</h2>\n    <span class="cnt">{{ stats.domain_jobs_list|length }}</span></div>\n  <div class="sec-body"><div class="tbl-wrap">\n  <table>\n    <thead><tr><th>Company</th><th>Title</th><th>Dept / Team</th><th>What this role does</th><th>Domain(s)</th></tr></thead>\n    <tbody>\n    {% for j in stats.domain_jobs_list %}\n    <tr>\n      <td><span class="badge badge-co" style="background:{{ company_color(j.company) }}">{{ company_label(j.company) }}</span></td>\n      <td><a href="{{ j.url }}" target="_blank" style="color:#302b63;text-decoration:none;font-weight:500">{{ j.title }}</a></td>\n      <td style="color:#666">{{ j.department }}</td>\n      <td style="color:#555;font-size:.82rem;max-width:320px">\n        {% if j.get("ai_summary") %}{{ j.ai_summary }}{% else %}<span style="color:#ccc">—</span>{% endif %}\n      </td>\n      <td>{% for dk in j.vertical_domains_list %}<span class="badge badge-v" style="margin:1px">{{ dom_label(dk) }}</span>{% endfor %}</td>\n\n    </tr>\n    {% endfor %}\n    </tbody>\n  </table>\n  </div></div>\n</div>\n{% endif %}\n</div>\n<script>\n(function(){\n  var tabs=document.querySelectorAll(".tab");\n  var panels=[document.getElementById("t0"),document.getElementById("t1"),document.getElementById("t2")];\n  if(!tabs.length)return;\n  panels.forEach(function(p,i){if(i>0&&p)p.style.display="none";});\n  tabs.forEach(function(tab,i){\n    tab.addEventListener("click",function(){\n      tabs.forEach(function(t){t.classList.remove("active");});\n      tab.classList.add("active");\n      panels.forEach(function(p){if(p)p.style.display="none";});\n      if(panels[i]){\n        panels[i].style.display="block";\n        // Let Plotly know the container is now visible and resize\n        setTimeout(function(){\n          var charts=panels[i].querySelectorAll(".plotly-graph-div");\n          charts.forEach(function(c){\n            if(window.Plotly)window.Plotly.relayout(c,{autosize:true});\n          });\n        },50);\n      }\n    });\n  });\n})();\n</script>\n</body></html>\n'
